"""Run an additional, caller supplied check without changing claim identity."""

from __future__ import annotations

import os
import shutil
import tempfile

from . import kernel
from ._kernel import build


def check(directory, command, *, files=None):
    """Judge present generated bytes with a check kept outside the claim.

    ``files`` maps paths in the temporary judging room to source file paths.
    The result is evidence for this invocation; it is never sealed as a pin.
    """
    parsed = kernel.load_recipe(directory)
    if not kernel.verify(directory)["ok"]:
        raise kernel.ClaimError("claim identity has drifted")
    with tempfile.TemporaryDirectory(prefix="reticuli-heldout-") as room:
        build._materialize(directory, room, parsed, generated=True)
        for name, source in (files or {}).items():
            from ._util import safe_path
            target = safe_path(room, name)
            os.makedirs(os.path.dirname(target), exist_ok=True)
            shutil.copyfile(source, target)
        result = kernel.run_gate(command, room, parsed)
    return {"ok": result["status"] == "ok", "result": result}


heldout = check
